import React from 'react';

// Without memoization - re-renders when parent re-renders
function ExpensiveComponent({ data }) {
  console.log('ExpensiveComponent rendered');
  return <div>{/* complex rendering */}</div>;
}

// With memoization - only re-renders when data changes
const MemoizedExpensiveComponent = React.memo(function ExpensiveComponent({ data }) {
  console.log('MemoizedExpensiveComponent rendered');
  return <div>{/* complex rendering */}</div>;
});

// Custom comparison function
const CustomMemoComponent = React.memo(
  function MyComponent({ data, timestamp }) {
    return <div>{/* rendering */}</div>;
  },
  (prevProps, nextProps) => {
    // Only re-render if data changes, ignore timestamp
    return prevProps.data === nextProps.data;
  }
);

import React, { useMemo } from 'react';

function DataProcessor({ items, filter }) {
  // Without useMemo - recalculates on every render
  const filteredItems = items.filter(item => 
    item.category === filter
  );

  const sortedItems = filteredItems.sort((a, b) => 
    a.value - b.value
  );

  // With useMemo - only recalculates when items or filter changes
  const processedItems = useMemo(() => {
    console.log('Processing items...');
    return items
      .filter(item => item.category === filter)
      .sort((a, b) => a.value - b.value);
  }, [items, filter]);

  return <div>{/* render processedItems */}</div>;
}

import React, { useState, useCallback } from 'react';

function ParentComponent() {
  const [count, setCount] = useState(0);

  // Without useCallback - new function on every render
  const handleClick = () => {
    setCount(count + 1);
  };

  // With useCallback - same function unless count changes
  const handleClickMemoized = useCallback(() => {
    setCount(prevCount => prevCount + 1);
  }, []); // Empty deps - function never changes

  return (
    <ChildComponent onClick={handleClickMemoized} />
  );
}

const ChildComponent = React.memo(function ChildComponent({ onClick }) {
  console.log('ChildComponent rendered');
  return <button onClick={onClick}>Click me</button>;
});

// Bad - creates new object on every render
function BadComponent() {
  const style = { color: 'red', fontSize: '16px' };
  return <div style={style}>Text</div>;
}

// Good - stable object reference
function GoodComponent() {
  const style = useMemo(() => ({ 
    color: 'red', 
    fontSize: '16px' 
  }), []);
  return <div style={style}>Text</div>;
}

// Better - move to constant outside component
const STABLE_STYLE = { color: 'red', fontSize: '16px' };

function BestComponent() {
  return <div style={STABLE_STYLE}>Text</div>;
}

